mapper.select:
SELECT id, parent_id, name, depth, sort_order, created_at, updated_at
FROM category
WHERE id = #{id}

mapper.update:
UPDATE category
SET name = #{name},
	sort_order = #{sortOrder},
	updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(1) > 0
FROM category
WHERE parent_id = #{parentId}
